import { RendererCanvas3DWireframe } from './renderer';
import { Delaunay } from 'd3-delaunay';

// Define a simple 2D point interface (since Voronoi/Delaunay are typically 2D)
interface Point {
  x: number;
  y: number;
  z?: number; // Optional z for 3D rendering, default to 0 if not provided
}

export class Solution {
  public div: HTMLElement;
  public renderer: RendererCanvas3DWireframe;
  public pts: Point[] = []; // Points array for mouse clicks
  public lns: [Point, Point][] = []; // Lines array for Delaunay edges
  public t: number = 0.0;
  private canvas: HTMLCanvasElement | null = null;
  private voronoiCells: [number, number][][] = []; // To store Voronoi cell polygons

  constructor(id: string) {
    this.div = document.getElementById(id) as HTMLElement;
    this.renderer = new RendererCanvas3DWireframe(id);
    this.renderer.pts = this.pts;

    // Initialize canvas and mouse click event
    this.setupCanvas();
    this.addMouseClickListener();

    this.init();
    this.update();
    this.render();
  }

  private setupCanvas(): void {
    // Assuming the renderer creates a canvas inside the div
    this.canvas = this.div.querySelector('canvas');
    if (!this.canvas) {
      console.error('Canvas not found in the div!');
      return;
    }
    // Set canvas dimensions (adjust as needed)
    this.canvas.width = this.div.clientWidth;
    this.canvas.height = this.div.clientHeight;
  }

  private addMouseClickListener(): void {
    if (!this.canvas) return;

    this.canvas.addEventListener('click', (event: MouseEvent) => {
      const rect = this.canvas!.getBoundingClientRect();
      const x = event.clientX - rect.left;
      const y = event.clientY - rect.top;

      // Normalize coordinates to [-1, 1] range for rendering (adjust based on your renderer)
      const normalizedX = (x / this.canvas!.width) * 2 - 1;
      const normalizedY = (y / this.canvas!.height) * -2 + 1; // Flip Y-axis for typical canvas orientation

      // Add the point (z = 0 for simplicity in 2D Voronoi/Delaunay)
      const newPoint: Point = { x: normalizedX, y: normalizedY, z: 0 };
      this.pts.push(newPoint);

      // Update the renderer points
      this.renderer.pts = this.pts;

      // Recalculate Voronoi and Delaunay
      this.computeVoronoiAndDelaunay();
    });
  }

  private computeVoronoiAndDelaunay(): void {
    if (this.pts.length < 3) return; // Need at least 3 points for meaningful triangulation

    // Prepare points for d3-delaunay (it works with 2D points)
    const points2D: [number, number][] = this.pts.map((p) => [p.x, p.y]);

    // Compute Delaunay triangulation
    const delaunay = Delaunay.from(points2D);

    // Clear previous lines
    this.lns = [];
    this.voronoiCells = [];

    // Extract Delaunay edges (lines connecting points)
    for (const [i, j] of delaunay.trianglePolygons().flatMap((poly) =>
      poly.map((_, idx) => [poly[idx], poly[(idx + 1) % poly.length]])
    )) {
      this.lns.push([this.pts[i], this.pts[j]]);
    }

    // Compute Voronoi diagram
    const voronoi = delaunay.voronoi([-1, -1, 1, 1]); // Bounds: adjust based on your canvas
    for (let i = 0; i < this.pts.length; i++) {
      const cell = voronoi.cellPolygon(i);
      if (cell) {
        this.voronoiCells.push(cell);
      }
    }

    // Update renderer lines (Delaunay edges)
    this.renderer.lns = this.lns;

    // Optionally, you can render Voronoi cells as lines by converting cells to line segments
    const voronoiLines: [Point, Point][] = [];
    for (const cell of this.voronoiCells) {
      for (let i = 0; i < cell.length; i++) {
        const p1 = cell[i];
        const p2 = cell[(i + 1) % cell.length];
        voronoiLines.push([
          { x: p1[0], y: p1[1], z: 0 },
          { x: p2[0], y: p2[1], z: 0 },
        ]);
      }
    }

    // Combine Delaunay and Voronoi lines (you can differentiate them by color in the renderer)
    this.renderer.lns = [...this.lns, ...voronoiLines];
  }

  public init(): void {
    // Optional: Add some initial points for testing
    // this.pts = [
    //   { x: -0.5, y: 0.5, z: 0 },
    //   { x: 0.5, y: 0.5, z: 0 },
    //   { x: 0, y: -0.5, z: 0 },
    // ];
    // this.computeVoronoiAndDelaunay();
  }

  public update(): void {
    this.t += 0.01;

    // Optional: Add animation or dynamic updates to points if needed
    // For example, you could make points oscillate in 3D space
    // this.pts.forEach((pt) => {
    //   pt.z = Math.sin(this.t) * 0.1;
    // });
  }

  public render(): void {
    requestAnimationFrame(() => {
      this.render();
    });
    this.update();
    this.renderer.render();
  }

  public destroy(): void {
    try {
      while (this.div && this.div.lastElementChild) {
        const lastChild = this.div.lastElementChild as Node;
        this.div.removeChild(lastChild);
      }
    } catch (error) {
      console.error('Error removing child elements:', error);
    }
  }
}